using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputUniformBeamProof{
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),common=File.ReadAllBytes(a[1]),pref=File.ReadAllBytes(a[2]),expected=File.ReadAllBytes(a[3]);int count=BitConverter.ToInt16(ds,0x8798),notes=BitConverter.ToInt16(ds,0x8792);var rows=new List<float[]>();for(int i=0;i<count;i++){var p=new float[15];Buffer.BlockCopy(common,i*60,p,0,60);rows.Add(p);}int[] map=new int[notes],stems=new int[notes];for(int i=1;i<notes;i++){map[i]=BitConverter.ToInt16(common,0x2b5a+i*2);stems[i]=BitConverter.ToInt16(common,0x2a2e+i*2);}var built=InputUniformBeam.Build(rows,map,stems,1,a.Length>4?float.Parse(a[4],System.Globalization.CultureInfo.InvariantCulture):4,0,200,BitConverter.ToSingle(pref,0));var r=built.Records;int expectedCount=a.Length>5?BitConverter.ToInt16(File.ReadAllBytes(a[5]),0x8798):count+1;if(r.Count!=expectedCount)throw new Exception("Record count "+r.Count+" != "+expectedCount);int checkedWords=0;for(int i=0;i<r.Count;i++)for(int p=0;p<15;p++){if(BitConverter.ToInt32(BitConverter.GetBytes(r[i][p]),0)!=BitConverter.ToInt32(expected,i*60+p*4))throw new Exception("Record "+i+" P"+(p+1)+": "+r[i][p]+" != "+BitConverter.ToSingle(expected,i*60+p*4));checkedWords++;}for(int n=1;n<notes;n++)if(built.ForcedStems[n]!=BitConverter.ToInt16(expected,0x2a2e+n*2))throw new Exception("Stem map "+n);Console.WriteLine("PASS "+checkedWords+" original uniform-beam working words");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
